import sys; sys.path.insert(0, str(WORK))
from cvlib import *
R = np.load(WORK/'base_reads.npz'); y=R['y']; res=np.load(WORK/'reserved.npy')
keep = np.setdiff1d(np.arange(768), res)
M = lambda L: R[f'mean_hidden_L{L}'][:,keep]
def zs(X): return (X-X.mean(0))/(X.std(0)+1e-6)
Y=np.eye(8)[y]
def feat_cv(X, fmap, lams, seeds=(0,1)):
    out={l:[] for l in lams}
    for s in seeds:
        f=folds(y,5,s)
        S={l:np.zeros((len(y),8)) for l in lams}
        for i in range(5):
            tr=f!=i; te=f==i
            mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6
            Ztr=(X[tr]-mu)/sd; Zte=(X[te]-mu)/sd
            Ftr, Fte = fmap(Ztr, Zte, y[tr])
            fm=Ftr.mean(0); Ftr=Ftr-fm; Fte=Fte-fm
            G=Ftr.T@Ftr; B=Ftr.T@(Y[tr]-Y[tr].mean(0))
            for l in lams:
                Wt=np.linalg.solve(G+l*np.eye(G.shape[0]),B); S[l][te]=Fte@Wt
        for l in lams: out[l].append((S[l].argmax(1)==y).mean())
    return {l:round(float(np.mean(v)),4) for l,v in out.items()}
rng=np.random.RandomState(0)
X=M(1)
def rand_tanh(a):
    def f(Ztr,Zte,ytr):
        d=Ztr.shape[1]; Wr=rng.randn(768,d)/np.sqrt(d)*a; b=rng.randn(768)*0.5
        return np.tanh(Ztr@Wr.T+b), np.tanh(Zte@Wr.T+b)
    return f
def nys_tanh(a, b0=0.0):
    def f(Ztr,Zte,ytr):
        d=Ztr.shape[1]; idx=rng.choice(len(Ztr),768,replace=False); C=Ztr[idx]/np.sqrt(d)
        Ctr=np.linalg.norm(C,axis=1)
        return np.tanh(a*(Ztr@C.T)/np.sqrt(d)/Ctr + b0), np.tanh(a*(Zte@C.T)/np.sqrt(d)/Ctr+b0)
    return f
for a in [0.5,1,2]:
    print('rand', a, feat_cv(X, rand_tanh(a), [0.1,1,10]))
for a in [1,2,4]:
    print('nys', a, feat_cv(X, nys_tanh(a), [0.1,1,10]))
